<script lang="ts">
 import {getContext,untrack} from 'svelte';import {goto} from '$app/navigation';import {AUTH_UI_CONTEXT,type AuthUiState} from '$lib/i18n/auth';import {Button} from '$lib/components/ui/button';import * as Card from '$lib/components/ui/card';import * as Field from '$lib/components/ui/field';import * as Dialog from '$lib/components/ui/dialog';import * as AlertDialog from '$lib/components/ui/alert-dialog';import {Input} from '$lib/components/ui/input';import ChoiceSelect from '$lib/components/forms/choice-select.svelte';import DatePicker from '$lib/components/forms/date-picker.svelte';import CurrencySelect from '$lib/components/forms/currency-select.svelte';import AmountInput from '$lib/components/forms/amount-input.svelte';import MoneyDisplay from '$lib/components/shared/money-display.svelte';import PageHeader from '$lib/components/shared/page-header.svelte';import LoadingScope from '$lib/components/shared/loading-scope.svelte';import ErrorState from '$lib/components/shared/error-state.svelte';import {formatDate} from '$lib/dates';
 let {billId}:{billId?:string}=$props();const workspace=getContext<{selectedId:string;ready:boolean;revision?:number;items:{id:string;currency:string;timezone:string}[]}>('capybudget-workspaces'),ui=getContext<AuthUiState>(AUTH_UI_CONTEXT),copy=(en:string,id:string)=>ui.locale==='id'?id:en;
 type Line={description:string;quantity:string;unitPrice:string;discountAmount:string;taxRateId:string|null};
 let items:any[]=$state([]),bill:any=$state(null),vendors:any[]=$state([]),accounts:any[]=$state([]),categories:any[]=$state([]),rates:any[]=$state([]),canWrite=$state(false),loading=$state(false),busy=$state(false),open=$state(false),error=$state(''),vendorId=$state(''),number=$state(''),issueDate=$state(''),dueDate=$state(''),currency=$state('IDR'),lines:Line[]=$state([]),amount=$state(''),paidOn=$state(''),accountId=$state(''),categoryId=$state(''),matching=$state(''),transactions:any[]=$state([]),paymentKey=$state(crypto.randomUUID()),correctionId=$state(''),correctionMode=$state('reverse'),reason=$state(''),effectiveOn=$state(''),sequence=0;
 let notice=$state(''),matchSearched=$state(false),issueConfirm=$state(false),currentDate=$state('');
 const endpoint=(ws:string)=>'/api/workspaces/'+ws;function today(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:workspace.items.find(w=>w.id===workspace.selectedId)?.timezone??'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=(key:string)=>parts.find(part=>part.type===key)?.value??'';return get('year')+'-'+get('month')+'-'+get('day');}
 async function call(path:string,method='GET',body?:unknown){const response=await fetch(path,{method,...(body===undefined?{}:{headers:{'content-type':'application/json'},body:JSON.stringify(body)})});const result=await response.json();if(!response.ok)throw new Error(result.message);return result;}
 async function load(ws:string,id?:string){const current=++sequence;loading=true;error='';try{const [data,contacts,wallets,cats,tax,access]=await Promise.all([call(endpoint(ws)+'/vendor-bills'+(id?'/'+id:'')),call(endpoint(ws)+'/contacts?kind=vendor'),call(endpoint(ws)+'/accounts'),call(endpoint(ws)+'/categories'),call(endpoint(ws)+'/business-tax'),call(endpoint(ws)+'/business-access')]);if(current===sequence&&ws===workspace.selectedId){items=data.items??[];bill=data.bill??null;vendors=contacts.items;accounts=wallets.items;categories=cats.items.filter((c:any)=>c.type==='expense');rates=tax.settings.enabled?tax.rates.filter((r:any)=>!r.archivedAt):[];canWrite=['owner','accountant'].includes(access.role);}}catch(e){if(current===sequence)error=e instanceof Error?e.message:String(e);}finally{if(current===sequence)loading=false;}}
 $effect(()=>{void workspace.revision;const id=billId;if(workspace.ready&&workspace.selectedId){const ws=workspace.selectedId;untrack(()=>{bill=null;items=[];canWrite=false;open=false;issueConfirm=false;correctionId='';notice='';matchSearched=false;amount='';accountId='';categoryId='';matching='';transactions=[];paymentKey=crypto.randomUUID();currentDate=today();paidOn=currentDate;void load(ws,id);});}});
 function edit(){vendorId=bill?.vendor_id??'';number=bill?.supplier_number??'';issueDate=bill?.issue_date??today();dueDate=bill?.due_date??today();currency=bill?.currency??workspace.items.find(w=>w.id===workspace.selectedId)?.currency??'IDR';lines=bill?bill.lines.map((l:any)=>({description:l.description,quantity:String(l.quantity),unitPrice:String(l.unit_price),discountAmount:String(l.discount_amount),taxRateId:rates.find(r=>r.name===l.tax_snapshot?.name)?.id??''})):[{description:'',quantity:'1',unitPrice:'',discountAmount:'0',taxRateId:''}];open=true;}
 async function mutate(path:string,method:string,body?:unknown){if(busy||loading)return null;const ws=workspace.selectedId;busy=true;error='';notice='';try{const result=await call(endpoint(ws)+path,method,body);if(ws!==workspace.selectedId)return null;await load(ws,billId);if(ws!==workspace.selectedId)return null;notice=copy('Supplier bill updated.','Tagihan pemasok diperbarui.');return result;}catch(e){if(ws===workspace.selectedId)error=e instanceof Error?e.message:String(e);return null;}finally{busy=false;}}
 async function save(event:SubmitEvent){event.preventDefault();const result=await mutate('/vendor-bills'+(bill?.state==='draft'?'/'+bill.id:''),bill?.state==='draft'?'PATCH':'POST',{vendorId,supplierNumber:number,issueDate,dueDate,currency,lines,version:bill?.version});if(result){open=false;if(!billId)await goto('/business/payables/'+result.bill.id);}}
 async function pay(event:SubmitEvent){event.preventDefault();if(!bill)return;const result=await mutate('/vendor-bills/'+bill.id+'/payments','POST',{amount,paidOn,accountId,categoryId,idempotencyKey:paymentKey,transactionId:matching||undefined});if(result){amount='';matching='';transactions=[];matchSearched=false;paymentKey=crypto.randomUUID();}}
 async function findMatches(){if(busy||loading)return;const ws=workspace.selectedId;busy=true;error='';matchSearched=false;try{const result=await call(endpoint(ws)+'/transactions?type=expense&limit=100');if(ws!==workspace.selectedId)return;matchSearched=true;transactions=result.items.filter((t:any)=>t.type==='expense'&&t.currency===bill.currency&&t.accountId===accountId&&t.categoryId===categoryId&&String(t.amount).replace(/\.0+$/,'')===amount.replace(/\.0+$/,'')&&t.date===paidOn);}catch(e){if(ws===workspace.selectedId)error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 function correct(id:string,mode='reverse'){correctionId=id;correctionMode=mode;reason='';effectiveOn=today();}
 async function confirmCorrection(){const path=correctionMode==='void'?'/vendor-bills/'+bill.id+'/void':'/vendor-bills/'+bill.id+'/payments/'+correctionId+'/reverse';if(await mutate(path,'POST',{reason,effectiveOn}))correctionId='';}
 function remaining(item:any){if(item.outstanding!==undefined)return String(item.outstanding);const units=(value:unknown)=>{const [whole,fraction='']=String(value??'0').split('.');return BigInt(whole)*10000n+BigInt(fraction.padEnd(4,'0'));};const amount=units(item.total)-units(item.paid??'0');return (amount/10000n).toString()+'.'+(amount%10000n).toString().padStart(4,'0');}
 function status(item:any){if(item.state==='draft')return copy('Draft · not finalized','Draf · belum dikonfirmasi');if(item.state==='void')return copy('Cancelled','Dibatalkan');if(/^0(?:\.0*)?$/.test(remaining(item)))return copy('Paid in full','Lunas');if(item.due_date<currentDate)return copy('Overdue','Lewat jatuh tempo');return !/^0(?:\.0*)?$/.test(String(item.paidAmount??item.paid??'0'))?copy('Partly paid','Dibayar sebagian'):copy('Unpaid','Belum dibayar');}
 function statusHelp(item:any){return item.state==='draft'?copy('Review the details, then finalize the bill before recording payments.','Tinjau detail, lalu konfirmasi tagihan sebelum mencatat pembayaran.'):item.state==='void'?copy('This bill is cancelled. Its original record remains in the history.','Tagihan ini dibatalkan. Catatan aslinya tetap tersimpan di riwayat.'): /^0(?:\.0*)?$/.test(remaining(item))?copy('Recorded payments cover the full bill amount.','Pembayaran tercatat telah mencakup seluruh jumlah tagihan.'):copy('Record payments already made, in full or in parts. The remaining balance appears in Receivables & payables.','Catat pembayaran yang sudah dilakukan, seluruhnya atau sebagian. Sisa tagihan muncul di Piutang & utang usaha.');}
 async function finalize(){issueConfirm=false;await mutate('/vendor-bills/'+bill.id+'/issue','POST');}
</script>
<svelte:head><title>CapyBudget · {copy('Vendor bills','Tagihan pemasok')}</title></svelte:head><LoadingScope active={loading||busy}/><PageHeader title={bill?.supplier_number??copy('Vendor bills','Tagihan pemasok')} description={copy('Track what your business owes suppliers, review due dates, and record full or partial payments.','Pantau utang bisnis kepada pemasok, tinjau jatuh tempo, dan catat pembayaran penuh atau sebagian.')}>
{#snippet actions()}{#if billId}<Button href="/business/payables" variant="outline">{copy('All supplier bills','Semua tagihan pemasok')}</Button>{/if}{#if canWrite&&(!bill||bill.state==='draft')}<Button disabled={loading||busy} onclick={edit}>{bill?copy('Edit draft','Edit draf'):copy('Add vendor bill','Tambah tagihan pemasok')}</Button>{/if}{/snippet}</PageHeader>
{#if error&&!open}<ErrorState title={copy('Could not update vendor bills','Tagihan pemasok gagal diperbarui')} message={error} onRetry={()=>load(workspace.selectedId,billId)} retryLabel={copy('Retry','Coba lagi')}/>{/if}
<div role="status" aria-live="polite">{#if notice}<p class="mb-6 rounded-[14px] border border-border bg-muted p-4 text-sm">{notice}</p>{/if}</div>
{#if !billId}<div class="space-y-6"><Card.Root><Card.Header><Card.Title>{copy('How supplier bills work','Cara kerja tagihan pemasok')}</Card.Title></Card.Header><Card.Content><ol class="grid gap-4 sm:grid-cols-3"><li class="space-y-2"><h2 class="text-sm font-semibold">{copy('1. Save a draft','1. Simpan draf')}</h2><p class="text-sm leading-relaxed text-muted-foreground">{copy('Choose a vendor and copy the dates, items, and amounts from their bill.','Pilih pemasok dan salin tanggal, item, serta jumlah dari tagihan mereka.')}</p></li><li class="space-y-2"><h2 class="text-sm font-semibold">{copy('2. Finalize the bill','2. Konfirmasi tagihan')}</h2><p class="text-sm leading-relaxed text-muted-foreground">{copy('Check the details first. Finalizing makes the bill available for payment recording and aging reports.','Periksa detail terlebih dahulu. Konfirmasi membuat tagihan tersedia untuk pencatatan pembayaran dan laporan jatuh tempo.')}</p></li><li class="space-y-2"><h2 class="text-sm font-semibold">{copy('3. Record payments','3. Catat pembayaran')}</h2><p class="text-sm leading-relaxed text-muted-foreground">{copy('Record a payment you have made, or link an expense already in your account. Partial payments reduce the remaining amount.','Catat pembayaran yang sudah dilakukan, atau tautkan pengeluaran yang sudah tercatat di akun. Pembayaran sebagian mengurangi sisa tagihan.')}</p></li></ol></Card.Content></Card.Root>
<Card.Root><Card.Header><Card.Title>{copy('Supplier bills','Tagihan pemasok')}</Card.Title><Card.Description>{copy('Showing up to 100 bills, ordered by due date. Full bill totals and remaining balances are labeled separately.','Menampilkan hingga 100 tagihan, diurutkan menurut jatuh tempo. Total tagihan dan sisa pembayaran diberi label terpisah.')}</Card.Description></Card.Header><Card.Content><ul class="divide-y divide-border">{#each items as item(item.id)}<li class="space-y-3 py-6 first:pt-0 last:pb-0"><div class="flex flex-wrap items-start justify-between gap-4"><div class="min-w-0 space-y-2"><a href={'/business/payables/'+item.id} class="inline-flex min-h-11 items-center rounded-[14px] font-semibold text-brand-ink underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-ring">{item.supplier_number}</a><p class="break-words text-sm">{item.vendor_snapshot.name}</p><span class="inline-flex rounded-full border border-border bg-muted px-3 py-1 text-sm font-semibold">{status(item)}</span><p class="text-sm text-muted-foreground">{copy('Due: ','Jatuh tempo: ')}{formatDate(item.due_date)}</p></div><dl class="grid gap-4 sm:grid-cols-2"><div class="space-y-1"><dt class="text-sm text-muted-foreground">{copy('Full bill total','Total tagihan')}</dt><dd><MoneyDisplay amount={String(item.total)} currency={item.currency}/></dd></div>{#if item.state==='open'}<div class="space-y-1"><dt class="text-sm text-muted-foreground">{copy('Still unpaid','Belum lunas')}</dt><dd><MoneyDisplay amount={remaining(item)} currency={item.currency} size="lg"/></dd></div>{/if}</dl></div></li>{/each}</ul>{#if !loading&&!error&&!items.length}<div class="space-y-3 rounded-[20px] border-2 border-border bg-muted/40 p-6"><h2 class="text-base font-semibold">{copy('Your first supplier bill starts here','Mulai dengan tagihan pemasok pertama')}</h2><p class="text-sm text-muted-foreground">{copy('Add a vendor to Customers & vendors, then save the bill they sent you.','Tambahkan pemasok ke Pelanggan & pemasok, lalu simpan tagihan yang mereka kirimkan.')}</p><Button href="/business/contacts" variant="outline">{copy('View vendors','Lihat pemasok')}</Button>{#if canWrite}<Button disabled={busy||loading} onclick={edit}>{copy('Add supplier bill','Tambah tagihan pemasok')}</Button>{/if}</div>{/if}</Card.Content></Card.Root></div>
{:else if bill}<div class="space-y-6"><Card.Root><Card.Header><Card.Title>{bill.vendor_snapshot.name}</Card.Title><Card.Description>{statusHelp(bill)}</Card.Description></Card.Header><Card.Content class="space-y-6"><p class="inline-flex rounded-full border-2 border-border bg-muted px-4 py-2 text-sm font-semibold">{status(bill)}</p><div class="grid gap-4 sm:grid-cols-3"><div><p class="text-sm text-muted-foreground">{copy('Full bill total','Total tagihan')}</p><MoneyDisplay amount={String(bill.total)} currency={bill.currency}/></div><div><p class="text-sm text-muted-foreground">{copy('Payments recorded','Pembayaran tercatat')}</p><MoneyDisplay amount={bill.paidAmount} currency={bill.currency}/></div>{#if bill.state==='open'}<div><p class="text-sm text-muted-foreground">{copy('Remaining bill balance','Sisa tagihan')}</p><MoneyDisplay amount={bill.outstanding} currency={bill.currency} size="xl"/></div>{/if}</div><dl class="grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-muted-foreground">{copy('Bill date','Tanggal tagihan')}</dt><dd>{formatDate(bill.issue_date)}</dd></div><div><dt class="text-sm text-muted-foreground">{copy('Due date','Jatuh tempo')}</dt><dd>{formatDate(bill.due_date)}</dd></div></dl><h2 class="text-base font-semibold">{copy('Purchased items and services','Barang dan jasa yang dibeli')}</h2><ul class="divide-y divide-border">{#each bill.lines as line(line.id)}<li class="flex flex-wrap items-center justify-between gap-3 py-3"><div class="space-y-1"><p class="text-sm font-semibold">{line.description}</p><p class="text-sm text-muted-foreground">{copy('Quantity: ','Jumlah unit: ')}{line.quantity} · {copy('Unit price: ','Harga satuan: ')}<MoneyDisplay amount={String(line.unit_price)} currency={bill.currency}/></p></div><MoneyDisplay amount={String(line.total_amount)} currency={bill.currency}/></li>{/each}</ul>{#if canWrite&&bill.state==='draft'}<Button disabled={busy} onclick={()=>issueConfirm=true}>{copy('Finalize bill','Konfirmasi tagihan')}</Button>{/if}{#if canWrite&&bill.state!=='void'}<Button variant="outline" disabled={busy} onclick={()=>correct(bill.id,'void')}>{copy('Void bill','Batalkan tagihan')}</Button>{/if}</Card.Content></Card.Root>
{#if canWrite&&bill.state==='open'&&!/^0(?:\.0*)?$/.test(bill.outstanding)}<Card.Root><Card.Header><Card.Title>{copy('Record a supplier payment','Catat pembayaran pemasok')}</Card.Title><Card.Description>{copy('Record a payment you have already made. Choose a partial amount or the full remaining balance. The paying account must use the bill’s currency.','Catat pembayaran yang sudah Anda lakukan. Pilih jumlah sebagian atau seluruh sisa tagihan. Akun pembayaran harus memakai mata uang yang sama dengan tagihan.')}</Card.Description></Card.Header><Card.Content><form onsubmit={pay} class="space-y-4"><div class="grid gap-4 sm:grid-cols-2"><Field.Field><Field.FieldLabel for="vendor-amount">{copy('Amount already paid','Jumlah yang sudah dibayar')}</Field.FieldLabel><AmountInput id="vendor-amount" bind:value={amount} currency={bill.currency} required/></Field.Field><Field.Field><Field.FieldLabel for="vendor-paid-on">{copy('Payment date','Tanggal pembayaran')}</Field.FieldLabel><DatePicker id="vendor-paid-on" bind:value={paidOn} required/></Field.Field><Field.Field><Field.FieldLabel for="vendor-account">{copy('Paying account','Akun pembayaran')}</Field.FieldLabel><ChoiceSelect id="vendor-account" bind:value={accountId} required items={[{value:'',label:copy('Select','Pilih')},...accounts.filter(a=>a.currency===bill.currency).map(a=>({value:a.id,label:a.name}))]}/></Field.Field><Field.Field><Field.FieldLabel for="vendor-category">{copy('Expense category','Kategori pengeluaran')}</Field.FieldLabel><ChoiceSelect id="vendor-category" bind:value={categoryId} required items={[{value:'',label:copy('Select','Pilih')},...categories.map(c=>({value:c.id,label:c.name}))]}/></Field.Field></div><Button type="button" variant="outline" disabled={busy||!amount||!accountId||!categoryId} onclick={findMatches}>{copy('Find existing expense (latest 100)','Cari pengeluaran yang ada (100 terbaru)')}</Button>{#if matchSearched&&!transactions.length}<p role="status" class="text-sm text-muted-foreground">{copy('No matching expense found among the latest 100. The amount, date, currency, account, and category must all match.','Tidak ditemukan pengeluaran yang cocok dalam 100 terbaru. Jumlah, tanggal, mata uang, akun, dan kategori harus sama.')}</p>{/if}{#if transactions.length}<Field.Field><Field.FieldLabel for="vendor-match">{copy('Existing expense (optional)','Pengeluaran yang ada (opsional)')}</Field.FieldLabel><ChoiceSelect id="vendor-match" bind:value={matching} items={[{value:'',label:copy('Create a new expense','Buat pengeluaran baru')},...transactions.map(t=>({value:t.id,label:formatDate(t.date)+' · '+(t.merchant??t.notes??copy('Expense','Pengeluaran'))}))]}/></Field.Field>{/if}<p class="text-sm text-muted-foreground">{copy('Choose an existing expense to link it without adding another ledger entry. Otherwise a new expense is recorded.','Pilih pengeluaran yang ada untuk ditautkan tanpa entri buku besar baru. Jika tidak, pengeluaran baru dicatat.')}</p><Button type="submit" disabled={busy||loading}>{copy('Confirm payment','Konfirmasi pembayaran')}</Button></form></Card.Content></Card.Root>{/if}
<Card.Root><Card.Header><Card.Title>{copy('Payment history','Riwayat pembayaran')}</Card.Title><Card.Description>{copy('Recorded payments reduce the bill balance. Reversing a payment corrects its accounting record using the date you choose.','Pembayaran tercatat mengurangi sisa tagihan. Membalikkan pembayaran mengoreksi pencatatan akuntansinya pada tanggal yang Anda pilih.')}</Card.Description></Card.Header><Card.Content><ul class="divide-y divide-border">{#each bill.payments as payment(payment.id)}<li class="flex flex-wrap items-center justify-between gap-3 py-3"><div><MoneyDisplay amount={payment.amount} currency={payment.currency}/><p class="text-sm text-muted-foreground">{formatDate(payment.paidOn)}{payment.reversedAt?' · '+copy('Recording reversed','Pencatatan dibatalkan'):''}</p></div>{#if canWrite&&!payment.reversedAt}<Button variant="outline" disabled={busy} onclick={()=>correct(payment.id)}>{copy('Reverse payment','Balikkan pembayaran')}</Button>{/if}</li>{/each}</ul>{#if !bill.payments.length}<p>{copy('No payments recorded.','Belum ada pembayaran.')}</p>{/if}</Card.Content></Card.Root></div>{/if}
<Dialog.Root {open} onOpenChange={next=>{if(!busy)open=next;}}><Dialog.Content class="max-h-[85dvh] overflow-auto p-6 sm:max-w-3xl" showCloseButton={!busy}><Dialog.Header><Dialog.Title>{bill?.state==='draft'?copy('Edit vendor bill','Edit tagihan pemasok'):copy('New vendor bill','Tagihan pemasok baru')}</Dialog.Title><Dialog.Description>{copy('Copy the supplier’s bill details. Save as a draft first, then review and finalize it before recording payments.','Salin detail tagihan pemasok. Simpan sebagai draf dahulu, lalu tinjau dan konfirmasi sebelum mencatat pembayaran.')}</Dialog.Description></Dialog.Header><form onsubmit={save} class="space-y-6">{#if error}<p role="alert">{error}</p>{/if}<div class="grid gap-4 sm:grid-cols-2"><Field.Field><Field.FieldLabel for="vendor-select">{copy('Supplier','Pemasok')}</Field.FieldLabel><ChoiceSelect id="vendor-select" aria-describedby="vendor-select-help" bind:value={vendorId} required items={[{value:'',label:copy('Select','Pilih')},...vendors.map(v=>({value:v.id,label:v.name}))]}/><p id="vendor-select-help" class="text-sm text-muted-foreground">{copy('Choose a saved vendor or a contact marked as both. Showing the first 50 matching contacts. Add missing suppliers in Customers & vendors.','Pilih pemasok tersimpan atau kontak dengan kedua jenis. Menampilkan 50 kontak pertama yang cocok. Tambahkan pemasok yang belum ada di Pelanggan & pemasok.')}</p></Field.Field><Field.Field><Field.FieldLabel for="supplier-number">{copy('Supplier’s bill / invoice number','Nomor tagihan / invoice pemasok')}</Field.FieldLabel><Input id="supplier-number" bind:value={number} maxlength={100} required aria-describedby="supplier-number-help"/><p id="supplier-number-help" class="text-sm text-muted-foreground">{copy('Use the number on the supplier’s document, e.g. INV-2026-021.','Gunakan nomor pada dokumen pemasok, mis. INV-2026-021.')}</p></Field.Field><Field.Field><Field.FieldLabel for="bill-issue">{copy('Bill date','Tanggal tagihan')}</Field.FieldLabel><DatePicker id="bill-issue" bind:value={issueDate} required/></Field.Field><Field.Field><Field.FieldLabel for="bill-due">{copy('Due date','Jatuh tempo')}</Field.FieldLabel><DatePicker id="bill-due" bind:value={dueDate} min={issueDate||undefined} required/></Field.Field><Field.Field><Field.FieldLabel for="bill-currency">{copy('Currency','Mata uang')}</Field.FieldLabel><CurrencySelect id="bill-currency" bind:value={currency}/></Field.Field></div>
<section class="space-y-4" aria-labelledby="vendor-lines"><h2 id="vendor-lines" class="text-base font-semibold">{copy('Items on the supplier’s bill','Item pada tagihan pemasok')}</h2><p class="text-sm text-muted-foreground">{copy('Enter each item’s quantity and unit price. Discounts are amounts, not percentages. Tax options follow your business tax settings and the bill date.','Masukkan jumlah unit dan harga satuan setiap item. Diskon berupa jumlah uang, bukan persentase. Pilihan pajak mengikuti pengaturan pajak bisnis dan tanggal tagihan.')}</p>{#each lines as line,i(i)}<div class="grid gap-3 rounded-[14px] border-2 border-border p-4 sm:grid-cols-2"><Field.Field><Field.FieldLabel for={'bill-line-'+i}>{copy('Description','Deskripsi')}</Field.FieldLabel><Input id={'bill-line-'+i} bind:value={line.description} maxlength={500} required/></Field.Field><Field.Field><Field.FieldLabel for={'bill-quantity-'+i}>{copy('Quantity','Jumlah unit')}</Field.FieldLabel><Input id={'bill-quantity-'+i} bind:value={line.quantity} inputmode="decimal" required/></Field.Field><Field.Field><Field.FieldLabel for={'bill-price-'+i}>{copy('Unit price','Harga satuan')}</Field.FieldLabel><AmountInput id={'bill-price-'+i} bind:value={line.unitPrice} {currency} required/></Field.Field><Field.Field><Field.FieldLabel for={'bill-discount-'+i}>{copy('Discount amount','Jumlah diskon')}</Field.FieldLabel><AmountInput id={'bill-discount-'+i} bind:value={line.discountAmount} {currency}/></Field.Field><Field.Field><Field.FieldLabel for={'bill-tax-'+i}>{copy('Purchase tax rate','Tarif pajak pembelian')}</Field.FieldLabel><ChoiceSelect id={'bill-tax-'+i} bind:value={line.taxRateId} items={[{value:'',label:copy('No tax rate selected','Tanpa tarif pajak')},...rates.filter(r=>r.effectiveFrom<=issueDate&&(!r.effectiveTo||r.effectiveTo>=issueDate)).map(r=>({value:r.id,label:r.name}))]}/></Field.Field>{#if lines.length>1}<Button type="button" variant="outline" onclick={()=>lines=lines.filter((_,n)=>n!==i)}>{copy('Remove line','Hapus baris')}</Button>{/if}</div>{/each}</section><Button type="button" variant="outline" disabled={busy||lines.length>=100} onclick={()=>lines=[...lines,{description:'',quantity:'1',unitPrice:'',discountAmount:'0',taxRateId:''}]}>{copy('Add line','Tambah baris')}</Button><Dialog.Footer><Button type="button" variant="outline" onclick={()=>open=false}>{copy('Cancel','Batal')}</Button><Button type="submit" disabled={busy||loading}>{copy('Save draft','Simpan draf')}</Button></Dialog.Footer></form></Dialog.Content></Dialog.Root>
<Dialog.Root open={!!correctionId} onOpenChange={(value)=>{if(!value&&!busy)correctionId='';}}><Dialog.Content class="max-h-[85dvh] overflow-y-auto sm:max-w-lg"><Dialog.Header><Dialog.Title>{correctionMode==='void'?copy('Void vendor bill','Batalkan tagihan pemasok'):copy('Reverse payment','Balikkan pembayaran')}</Dialog.Title><Dialog.Description>{correctionMode==='void'?copy('Cancel this bill with an effective date and reason. Reverse all recorded payments first. The original record stays in your history.','Batalkan tagihan ini dengan tanggal berlaku dan alasan. Balikkan semua pencatatan pembayaran terlebih dahulu. Catatan asli tetap tersimpan di riwayat.'):copy('Correct a payment recorded by mistake. This reverses the recorded expense and makes the amount unpaid again. It records a correction; arrange any real refund with the supplier separately.','Koreksi pembayaran yang keliru dicatat. Ini membalikkan pencatatan pengeluaran dan membuat jumlah tersebut belum dibayar lagi. Ini mencatat koreksi; urus pengembalian dana nyata secara terpisah dengan pemasok.')}</Dialog.Description></Dialog.Header><Field.Field><Field.FieldLabel for="bill-reason">{copy('Reason','Alasan')}</Field.FieldLabel><Input id="bill-reason" bind:value={reason} maxlength={1000}/></Field.Field><Field.Field><Field.FieldLabel for="bill-effective">{copy('Effective date','Tanggal efektif')}</Field.FieldLabel><DatePicker id="bill-effective" bind:value={effectiveOn}/></Field.Field><Dialog.Footer><Button variant="outline" disabled={busy} onclick={()=>correctionId=''}>{copy('Cancel','Batal')}</Button><Button variant="destructive" disabled={busy||!reason.trim()||!effectiveOn} onclick={confirmCorrection}>{copy('Confirm correction','Konfirmasi koreksi')}</Button></Dialog.Footer></Dialog.Content></Dialog.Root>

<AlertDialog.Root open={issueConfirm} onOpenChange={next=>{if(!busy)issueConfirm=next;}}><AlertDialog.Content><AlertDialog.Header><AlertDialog.Title>{copy('Finalize this supplier bill?','Konfirmasi tagihan pemasok ini?')}</AlertDialog.Title><AlertDialog.Description>{copy('Review the supplier, document number, dates, currency, and line amounts. Once finalized, this bill is included in payment tracking and aging reports. Its draft details can no longer be edited.','Tinjau pemasok, nomor dokumen, tanggal, mata uang, serta jumlah setiap baris. Setelah dikonfirmasi, tagihan disertakan dalam pelacakan pembayaran dan laporan jatuh tempo. Detail drafnya tidak dapat diedit lagi.')}</AlertDialog.Description></AlertDialog.Header><AlertDialog.Footer><AlertDialog.Cancel disabled={busy} onclick={()=>issueConfirm=false}>{copy('Review draft','Tinjau draf')}</AlertDialog.Cancel><Button disabled={busy||loading} onclick={finalize}>{copy('Finalize bill','Konfirmasi tagihan')}</Button></AlertDialog.Footer></AlertDialog.Content></AlertDialog.Root>
